package com.example.rokidgeminisecretary;
import android.content.*;import android.net.*;import android.app.*;import android.widget.*;import org.json.*;
/** Local-only reader. Connectivity indicators are observations, never provider probes. */
final class OfflineAccess {
 static String describe(boolean link,String network){return "保存済みメモ・回答：通信なしで閲覧できます（スマホに保存された分）\nスマホ↔メガネ："+(link?"最近の状態受信あり":"接続未確認")+"\nスマホのインターネット："+network+"\nAIへの新しい質問・画像解析にはメガネ側の通信も必要です。AI接続は送信するまで未確認です。";}
 static String status(MainActivity c){String network="未確認";try{ConnectivityManager m=(ConnectivityManager)c.getSystemService(Context.CONNECTIVITY_SERVICE);NetworkCapabilities n=m==null?null:m.getNetworkCapabilities(m.getActiveNetwork());network=n==null?"利用可能な接続なし":n.hasCapability(NetworkCapabilities.NET_CAPABILITY_VALIDATED)?"OSが接続を確認":"接続あり・インターネット未確認";}catch(SecurityException unavailable){}JSONObject state=ConversationWorkspace.snapshot(c);String detail=describe(state.optBoolean("connected"),network);JSONObject sync=state.optJSONObject("answerSync");detail+="\nメガネの未取り込み回答："+(sync!=null&&sync.optBoolean("readable")?sync.optInt("pendingAnswers")+"件"+(state.optBoolean("connected")?"":"（最終受信時点・現在は未確認）"):"未確認");try{JSONObject reconnect=ReconnectReview.status(c);long returned=reconnect.optLong("returnedAt"),age=System.currentTimeMillis()-returned;if(returned>0&&age>=0&&age<120000)detail+="\n接続が戻りました。送信待ち "+reconnect.getJSONArray("held").length()+"件は内容確認後に許可してください。";}catch(Exception ignored){}return detail;}
 static String compact(MainActivity c){JSONObject state=ConversationWorkspace.snapshot(c),sync=state.optJSONObject("answerSync");String pending=sync!=null&&sync.optBoolean("readable")?sync.optInt("pendingAnswers")+"件"+(state.optBoolean("connected")?"":"（最終受信時点）"):"未確認";String text="保存済みメモ・回答を開く（通信不要）\nメガネ："+(state.optBoolean("connected")?"最近の受信あり":"接続未確認")+" / 未取り込み回答："+pending;try{JSONObject reconnect=ReconnectReview.status(c);long age=System.currentTimeMillis()-reconnect.optLong("returnedAt");if(reconnect.optLong("returnedAt")>0&&age>=0&&age<120000)text+="\n接続が戻りました。送信待ちの内容を確認してください";}catch(Exception ignored){}return text;}
 static TextView indicator(MainActivity c){TextView v=new TextView(c);v.setTextSize(12);v.setText(compact(c));v.setContentDescription("通信状態。タップして保存済みメモ・回答を開く");v.setOnClickListener(a->show(c));Runnable tick=new Runnable(){public void run(){if(c.isDestroyed()||!v.isAttachedToWindow())return;v.setText(compact(c));v.postDelayed(this,5000);}};v.addOnAttachStateChangeListener(new android.view.View.OnAttachStateChangeListener(){public void onViewAttachedToWindow(android.view.View x){v.removeCallbacks(tick);v.post(tick);}public void onViewDetachedFromWindow(android.view.View x){v.removeCallbacks(tick);}});return v;}
 static JSONArray select(JSONObject catalog,String filter,String query)throws Exception{java.util.ArrayList<JSONObject> found=new java.util.ArrayList<>();JSONArray rows=catalog.getJSONArray("items");for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);String type=row.optString("type");boolean memo=type.equals("memo")||type.equals("continuation")||type.equals("draft");if(!(memo||type.equals("conversation")||type.equals("reading")))continue;if(filter.equals("memo")&&!memo||filter.equals("answer")&&memo)continue;if(!query.trim().isEmpty()&&!RecordSearchPolicy.matches(row.optString("title")+" "+row.optString("body"),query))continue;found.add(row);}found.sort((a,b)->Long.compare(b.optLong("at"),a.optLong("at")));JSONArray out=new JSONArray();for(int i=0;i<Math.min(100,found.size());i++)out.put(found.get(i));return out;}
 static JSONObject catalog(MainActivity c)throws Exception{JSONObject data=UnifiedRecords.catalog(c);try{JSONArray drafts=OfflineNotes.read(c),rows=data.getJSONArray("items");for(int i=0;i<drafts.length();i++){JSONObject d=drafts.getJSONObject(i);rows.put(UnifiedRecords.item("draft",d.getString("id"),d.optLong("at"),"未送信メモ",d.optString("text")));}}catch(Exception unavailable){data.getJSONArray("issues").put("未送信メモ");}return data;}
 static void show(MainActivity c){ReliabilityDialog ui=new ReliabilityDialog(c);LinearLayout b=ui.box();ui.text(b,status(c));ui.button(b,"送信待ちの内容・接続トラブルを確認",()->QueuedConversationDialog.show(c,()->c.openConversationRecovery()));ui.text(b,"このスマホに保存済みの本文を表示します。メガネの転送待ちは接続中に順次取り込みます。更新前の履歴はメガネに残った短い抜粋だけの場合があります。未保存の回答は復元できません。新しい回答は生成しません。");EditText q=ui.field(b,"保存済み本文を検索（空欄で一覧）","",160);Spinner filter=new Spinner(c);filter.setAdapter(new ArrayAdapter<String>(c,android.R.layout.simple_spinner_dropdown_item,new String[]{"すべて","メモ・未送信メモ","会話・読み取り回答"}));b.addView(filter);TextView scope=new TextView(c);b.addView(scope);LinearLayout list=ui.box();Button refresh=new Button(c);refresh.setText("保存済みの一覧を表示・更新");b.addView(refresh);b.addView(list);AlertDialog dialog=new AlertDialog.Builder(c).setTitle("保存済みメモ・回答（通信不要）").setView(scroll(c,b)).setPositiveButton("閉じる",null).create();refresh.setOnClickListener(v->{String query=q.getText().toString(),kind=new String[]{"","memo","answer"}[filter.getSelectedItemPosition()];refresh.setEnabled(false);new Thread(()->{try{JSONObject data=catalog(c);JSONArray rows=select(data,kind,query);c.runOnUiThread(()->{if(!dialog.isShowing()||c.isDestroyed())return;list.removeAllViews();scope.setText("保存日時順・最大100件 / 表示 "+rows.length()+"件\n取得できない分類・制限："+data.optJSONArray("issues")+"\n古い保存内容は現在の状況と異なる場合があります。");if(rows.length()==0)ui.text(list,"該当する保存済み本文はありません。未取得の分類がある場合は保存状態を確認してください。");for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);ui.button(list,row.optString("title")+" / "+new java.util.Date(row.optLong("at")),()->{if(row.optJSONObject("answer")!=null){AnswerCorrectionDialog.show(c,row.optJSONObject("answer"));return;}TextView text=new TextView(c);text.setPadding(20,12,20,12);text.setTextIsSelectable(true);text.setText("端末内の保存内容 / "+new java.util.Date(row.optLong("at"))+"\n\n"+row.optString("body"));new AlertDialog.Builder(c).setTitle("保存済み本文（通信不要）").setView(scroll(c,text)).setPositiveButton("閉じる",null).show();});}});}catch(Exception failure){c.runOnUiThread(()->{if(dialog.isShowing())scope.setText("保存済み本文を読み取れません。元の記録は変更していません。");});}finally{c.runOnUiThread(()->refresh.setEnabled(true));}},"OfflineRecordReader").start();});dialog.show();refresh.performClick();}
 static ScrollView scroll(MainActivity c,android.view.View v){ScrollView s=new ScrollView(c);s.addView(v);return s;}
 private OfflineAccess(){}
}
